from pathlib import Path
import json,numpy as np
W=Path(__file__).resolve().parents[1];a=json.loads((W/'runs/recontact_rhs_fixed/result.json').read_text());b=json.loads((W/'runs/recontact_rhs_fixed_half/result.json').read_text());x=np.load(W/'runs/recontact_rhs_fixed/trajectory.npz');y=np.load(W/'runs/recontact_rhs_fixed_half/trajectory.npz');assert np.allclose(x['t'],y['t'],atol=1e-12)
fa=np.array([r['force'] for r in a['rows']]);fb=np.array([r['force'] for r in b['rows']]);t=x['t'];rel=abs(fa-fb)/np.maximum(abs(fb),1e-4);ja=np.trapezoid(fa,t);jb=np.trapezoid(fb,t);pos=np.linalg.norm(x['x']-y['x'],axis=-1).max();work=abs(a['friction_dissipated_J']-b['friction_dissipated_J'])/max(abs(b['friction_dissipated_J']),1e-8)
# Preserve the same denominator-floor convention used for CAD contact comparison.
checks={'both_complete':a['status']==b['status']=='completed','loaded':min(fa.max(),fb.max())>1e-4,'unloaded':max(abs(fa[-1]),abs(fb[-1]))<1e-4,'positive_gap_final':min(a['rows'][-1]['x_gap'],b['rows'][-1]['x_gap'])>0,'receding_final':all(r['rows'][-1]['mean_v_left'][0]<0 and r['rows'][-1]['mean_v_right'][0]>0 for r in [a,b]),'tangential_momentum_transferred':all(r['rows'][-1]['mean_v_right'][2]>0 for r in [a,b]),'history_unchanged':a['history_identical'] and b['history_identical'],'position':pos<1e-4,'force':rel.max()<.05,'impulse':abs(ja-jb)/max(abs(jb),1e-7)<.05,'friction_work':work<.05,'force_balance':max(a['max_net_force_N'],b['max_net_force_N'])<1e-8,'moment_balance':max(a['max_net_moment_Nm'],b['max_net_moment_Nm'])<1e-8,'momentum':max(a['total_momentum_error_Ns'],b['total_momentum_error_Ns'])<1e-8,'energy':all(max(abs(row['energy_residual']) for row in r['rows'])/max(r['initial_energy_J'],1e-8)<.05 for r in [a,b])}
res={'position_m':float(pos),'force_max_relative_or_floor':float(rel.max()),'impulse_relative_or_floor':float(abs(ja-jb)/max(abs(jb),1e-7)),'friction_work_relative_or_floor':float(work),'friction_work_absolute_difference_J':abs(a['friction_dissipated_J']-b['friction_dissipated_J']),'force_peak_coarse_N':float(fa.max()),'force_peak_refined_N':float(fb.max()),'coarse_energy_residual_ratio':max(abs(row['energy_residual']) for row in a['rows'])/a['initial_energy_J'],'refined_energy_residual_ratio':max(abs(row['energy_residual']) for row in b['rows'])/b['initial_energy_J']};out={'status':'pass' if all(checks.values()) else 'fail','checks':checks,'results':res,'scope':'Initial pre-separated fragments; no physical cutting claim'};(W/'recontact_comparison.json').write_text(json.dumps(out,indent=2,default=lambda x:x.item()));print(json.dumps(out,indent=2,default=lambda x:x.item()))
